"""Publish the actual before/after screenshots and final browser evidence."""
from pathlib import Path
from html import escape
import json

DIR = Path(__file__).resolve().parent
before = json.loads((DIR / 'before/capture-results.json').read_text())
after = json.loads((DIR / 'after/browser-results.json').read_text())
regression = json.loads((DIR / 'quiz-compare/browser-results.json').read_text())
labels = {'desktop': 'Desktop · 1440 × 1000', 'landscape': 'iPad landscape viewport · 1194 × 834', 'portrait': 'iPad portrait viewport · 768 × 1024', 'mobile': 'Mobile viewport · 390 × 844', 'narrow': 'Narrow mobile · 320 × 740', 'portrait-edge': 'Large portrait tablet · 1024 × 1366'}
def image_file(filename):
    file = DIR / filename
    if not file.is_file(): file = file.with_suffix('.webp')
    assert file.is_file(), file
    return str(file.relative_to(DIR))
sections = []
for size, label in labels.items():
    parts = []
    for suffix, name in [('categories', 'Guitar categories'), ('features', 'Three mode cards'), ('home', 'Complete Homepage')]:
        old = image_file(f'before/chromium-{size}-{suffix}.png')
        new = image_file(f'after/chromium-{size}-{suffix}.png')
        parts.append(f'<h3>{name}</h3><div class="pair"><figure><figcaption>Before · 3c1d70e</figcaption><a href="{old}"><img src="{old}" loading="lazy" alt="Before: {name}"></a></figure><figure><figcaption>After · tested build</figcaption><a href="{new}"><img src="{new}" loading="lazy" alt="After: {name}"></a></figure></div>')
    cards = []
    for key, title in [('home-practice', 'Practice'), ('find', 'Find My Guitar'), ('compare', 'Compare')]:
        file = image_file(f'after/chromium-{size}-{key}-card.png')
        cards.append(f'<figure><figcaption>{title} · individual card capture</figcaption><a href="{file}"><img src="{file}" loading="lazy" alt="{title} card after the update"></a></figure>')
    parts.append('<h3>Individual mode cards after the update</h3><div class="cards">' + ''.join(cards) + '</div>')
    sections.append(f'<section><h2>{escape(label)}</h2>{"".join(parts)}</section>')
passed = sum(c['passed'] for c in after['checks'])
total = len(after['checks'])
status = 'PASS' if after['passed'] else 'FAILED — inspect raw report'
page = f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fretline Homepage · Actual before / after</title><style>body{{margin:0;background:#090a0a;color:#ece8df;font:15px/1.6 system-ui,sans-serif;padding:32px;max-width:1500px}}h1,h2,h3{{font-weight:500}}h1,h2,a{{color:#e5bd70}}h2{{margin-top:48px}}h3{{margin-top:32px}}.pair,.cards{{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start}}.cards{{grid-template-columns:repeat(3,minmax(0,1fr))}}figure{{margin:0;background:#131414;border:1px solid #806c422e;border-radius:8px;overflow:hidden}}figcaption{{padding:10px}}img{{display:block;width:100%;height:auto}}code{{overflow-wrap:anywhere}}@media(max-width:650px){{body{{padding:16px}}.pair,.cards{{grid-template-columns:1fr}}}}</style><h1>Fretline Homepage — actual before / after</h1><p>Browser result: <strong>{passed}/{total} grouped checks · {status}</strong>. Chromium screenshots at matching viewport sizes. Click a screenshot to inspect its original resolution.</p><p>Linux WebKit was also executed. These are automated browser viewport checks, not a physical iPad Safari test.</p><p>Tall element captures can include fixed navigation within the stitched image. Those raw before/after captures are retained; individual card captures below provide a clearer view. No product CSS was hidden for screenshots.</p><p><a href="after/browser-results.json">Actual browser report</a> · <a href="quiz-compare/browser-results.json">Unchanged Quiz/Compare regression</a> · <a href="before/capture-results.json">Baseline provenance</a></p>{''.join(sections)}</html>'''
(DIR / 'before-after.html').write_text(page)
errors = {k: len(after[k]) for k in ['consoleErrors', 'runtimeErrors', 'networkErrors', 'failedRequests']}
lines = ['# Actual Homepage browser verification', '', f'- Final result: **{passed}/{total} grouped checks**, overall **{status}**.', f'- Engines: {json.dumps(after["browserVersions"])}.', '- Viewports: Desktop 1440×1000; iPad landscape 1194×834; portrait 768×1024; Mobile 390×844; narrow Mobile 320×740; portrait tablet 1024×1366.', '- Native iPadOS Safari / physical iPad: **not tested**. Linux WebKit and synthetic touch were actually executed.', f'- Console/runtime/HTTP/request errors: `{json.dumps(errors)}`.', f'- Source and build unchanged during the final run: `{after["sourceAndBuildUnchangedDuringRun"]}`.', f'- Before HTML SHA-256: `{before["servedHTMLSHA256"]}`.', f'- After HTML SHA-256: `{after["servedHTMLSHA256"]}`.', '', 'Checks cover category image decoding/full-frame fit, 2×2 or stacked layout, actual Catalog counts and routes, the exact authorized Practice/Find/Compare copy and CTA routes, responsive card geometry, text containment and page overflow, preserved Hero/brand/Featured, real search/wishlist/Compare state and Practice42 selection, Hero autoplay and brand autoplay/drag/resume.', '', '[Before / after gallery](before-after.html) · [Raw browser result](after/browser-results.json)', '', '## Individual final checks', '']
lines.extend(f'- {"PASS" if c["passed"] else "FAIL"} `{c["name"]}`' for c in after['checks'])
lines += ['', '## Unchanged Quiz / Compare regression', '', f'- Original checker: `docs/final-ui-refinement/tests/quiz-compare-browser.py`, not edited for this work.', f'- Final result: **{sum(c["passed"] for c in regression["checks"])}/{len(regression["checks"])}**, overall **{regression["passed"]}**.', '- Both actual Chromium and WebKit; Desktop and Mobile five-step Quiz flow, six frozen recommendation fixtures per engine, real four-model Compare/picker/limit/tabs/differences/share/remove/history/reload/clear, additional responsive widths, actual Chromium clipboard.', '- [Raw regression report](quiz-compare/browser-results.json).', '', '## Retained initial diagnostics', '', 'The first incomplete run found real category minimum-width overflow at 768px, 390px and 1024px portrait. The application CSS was fixed before final acceptance. A separate harness issue compared viewport coordinates recorded after separate lazy-image scrolling; final geometry uses document coordinates with the original row/column/containment/overflow thresholds. Both initial incomplete reports are retained under `diagnostic-before-category-fix/` and `diagnostic-incomplete-quiz-compare/`; they are not counted as final passing suites.', '', 'The subsequent `diagnostic-font-navigation/` run passed all42 functional/layout groups but correctly failed overall because rapid Practice-to-Home hard navigation cancelled one WebKit Instrument Serif italic font request. Before final acceptance the harness was changed to await two actual paint frames and document.fonts.ready before leaving a page, with no application changes and the zero-cancellation criterion retained. The final42-case focused run was rerun fully on the same frozen application build; the already clean13-case original Quiz/Compare result was retained.', '', 'Tall raw component screenshots can contain fixed navigation in the stitched capture. Individual final mode-card captures avoid most of that artifact without hiding product CSS.']
(DIR / 'browser-report.md').write_text('\n'.join(lines) + '\n')
checks = [{'name': c['name'], 'suite': 'homepage-focused', 'passed': c['passed']} for c in after['checks']] + [{'name': c['case'], 'suite': 'original-quiz-compare', 'passed': c['passed']} for c in regression['checks']]
assert len({c['name'] for c in checks}) == len(checks)
summary = {'passed': after['passed'] and regression['passed'], 'passedChecks': sum(c['passed'] for c in checks), 'totalUniqueChecks': len(checks), 'suites': [{'name': 'homepage-focused', 'report': 'after/browser-results.json', 'passed': after['passed'], 'passedChecks': sum(c['passed'] for c in after['checks']), 'totalChecks': len(after['checks'])}, {'name': 'original-quiz-compare', 'report': 'quiz-compare/browser-results.json', 'passed': regression['passed'], 'passedChecks': sum(c['passed'] for c in regression['checks']), 'totalChecks': len(regression['checks']), 'originalCheckerChanged': False}], 'checks': checks, 'browserVersions': after['browserVersions'], 'viewports': [{'name': k, 'width': row['size'][0], 'height': row['size'][1]} for row in before['captures'] for k in [row['viewport']]], 'physicalIPadSafariTested': False, 'unexpectedEvents': {k: len(after[k]) + len(regression[k]) for k in ['consoleErrors', 'runtimeErrors', 'networkErrors', 'failedRequests']}, 'sourceAndBuildUnchangedDuringFinalRuns': after['sourceAndBuildUnchangedDuringRun'] and regression['sourceAndBuildUnchangedDuringRun'], 'frozenBuildHTMLSHA256': after['servedHTMLSHA256'], 'beforeBuildHTMLSHA256': before['servedHTMLSHA256'], 'beforeAfterGallery': 'before-after.html', 'diagnostics': [{'report': 'diagnostic-before-category-fix/browser-results.json', 'status': 'incomplete diagnostic, real minimum-width overflow fixed in application CSS; coordinate-measurement harness issue fixed without reducing geometry criteria'}, {'report': 'diagnostic-incomplete-quiz-compare/browser-results.json', 'status': 'interrupted diagnostic before application rebuild; original checker rerun fully and passed13/13'}, {'report': 'diagnostic-font-navigation/browser-results.json', 'status': '42/42 functional groups passed but overall failed due one cancelled WebKit font; harness now waits actual paint/fonts before navigation, zero-cancellation criterion unchanged; same application build rerun fully42/42 with zero events'}], 'notes': ['All final browser cases were actually executed. No physical iPad or iPadOS Safari certification is claimed.', 'Screenshot storage compression does not alter pixels or test assertions/results.']}
optimization = DIR / 'screenshot-optimization.json'
if optimization.is_file():
    manifest = json.loads(optimization.read_text())
    summary['screenshotStorage'] = {'manifest': 'screenshot-optimization.json', 'format': manifest['format'], 'count': manifest['screenshotCount'], 'originalPNGBytes': manifest['originalPNGBytes'], 'losslessWebPBytes': manifest['losslessWebPBytes'], 'uniqueOriginalPNGBytes': manifest['uniqueOriginalPNGBytes'], 'uniqueLosslessWebPBytes': manifest['uniqueLosslessWebPBytes'], 'allPixelComparisonsAEZero': all(r['absoluteErrorPixels'] == 0 for r in manifest['records']), 'rawReportArchivesPreserved': True}
(DIR / 'summary.json').write_text(json.dumps(summary, ensure_ascii=False, indent=2) + '\n')
print('Published gallery and actual browser report:', passed, '/', total, status)
